class TenantRateLimiter {
  private buckets = new Map<string, { tokens: number; last: number }>();
  allow(tenantId: string, rate = 100): boolean {
    const b = this.buckets.get(tenantId) ?? { tokens: rate, last: Date.now() };
    const elapsed = (Date.now() - b.last) / 1000;
    b.tokens = Math.min(rate, b.tokens + elapsed * rate);
    b.last = Date.now();
    if (b.tokens < 1) return false;
    b.tokens -= 1;
    this.buckets.set(tenantId, b);
    return true;
  }
}

